1008:         Gia_ManLevelNum( p->pAig );
1009:         Gia_ManForEachObj( p->pAig, pObj, i )
1010:             Gia_ObjSetRepr( p->pAig, i, (Gia_ObjIsAnd(pObj) && Gia_ObjLevel(p->pAig,pObj) <= LevelMax) ? 0 : GIA_VOID );
1011:         Vec_IntFreeP( &p->pAig->vLevels );
