1014:     if ( p->pPars->fSeqSimulate )
1015:         Gia_ManForEachRo( p->pAig, pObj, i )
1016:             if ( pObj->Value )
1017:                 Gia_ObjSetRepr( p->pAig, Gia_ObjId(p->pAig, pObj), 0 );
1018:     // perform simulation
