437: void Gia_ManCorrSpecReduce_rec( Gia_Man_t * pNew, Gia_Man_t * p, Gia_Obj_t * pObj, int f, int nPrefix )
438: {
439:     Gia_Obj_t * pRepr;
440:     int iLitNew;
441:     if ( ~Gia_ObjCopyF(p, f, pObj) )
442:         return;
443:     if ( f >= nPrefix && (pRepr = Gia_ObjReprObj(p, Gia_ObjId(p, pObj))) )
444:     {
445:         Gia_ManCorrSpecReduce_rec( pNew, p, pRepr, f, nPrefix );
446:         iLitNew = Abc_LitNotCond( Gia_ObjCopyF(p, f, pRepr), Gia_ObjPhase(pRepr) ^ Gia_ObjPhase(pObj) );
