450:     assert( Gia_ObjIsCand(pObj) );
451:     iLitNew = Gia_ManCorrSpecReal( pNew, p, pObj, f, nPrefix );
452:     Gia_ObjSetCopyF( p, f, pObj, iLitNew );
453: }
