466: Gia_Man_t * Gia_ManCorrSpecReduce( Gia_Man_t * p, int nFrames, int fScorr, Vec_Int_t ** pvOutputs, int fRings, Vec_Int_t ** pvOutLits )
467: {
468:     Gia_Man_t * pNew, * pTemp;
469:     Gia_Obj_t * pObj, * pRepr;
470:     Vec_Int_t * vXorLits;
471:     int f, i, iPrev, iObj, iPrevNew, iObjNew, iPrevRaw, iObjRaw;
472:     assert( nFrames > 0 );
473:     assert( Gia_ManRegNum(p) > 0 );
474:     assert( p->pReprs != NULL );
475:     Vec_IntFill( &p->vCopies, (nFrames+fScorr)*Gia_ManObjNum(p), -1 );
476:     Gia_ManSetPhase( p );
477:     pNew = Gia_ManStart( nFrames * Gia_ManObjNum(p) );
478:     pNew->pName = Abc_UtilStrsav( p->pName );
479:     pNew->pSpec = Abc_UtilStrsav( p->pSpec );
480:     Gia_ManHashAlloc( pNew );
481:     Gia_ObjSetCopyF( p, 0, Gia_ManConst0(p), 0 );
482:     Gia_ManForEachRo( p, pObj, i )
483:         Gia_ObjSetCopyF( p, 0, pObj, Gia_ManAppendCi(pNew) );
484:     Gia_ManForEachRo( p, pObj, i )
485:         if ( (pRepr = Gia_ObjReprObj(p, Gia_ObjId(p, pObj))) )
486:             Gia_ObjSetCopyF( p, 0, pObj, Gia_ObjCopyF(p, 0, pRepr) );
487:     for ( f = 0; f < nFrames+fScorr; f++ )
488:     { 
489:         Gia_ObjSetCopyF( p, f, Gia_ManConst0(p), 0 );
490:         Gia_ManForEachPi( p, pObj, i )
491:             Gia_ObjSetCopyF( p, f, pObj, Gia_ManAppendCi(pNew) );
492:     }
493:     *pvOutputs = Vec_IntAlloc( 1000 );
494:     if ( pvOutLits )
495:         *pvOutLits = Vec_IntAlloc( 1000 );
496:     vXorLits = Vec_IntAlloc( 1000 );
497:     if ( fRings )
498:     {
499:         Gia_ManForEachObj1( p, pObj, i )
500:         {
501:             if ( Gia_ObjIsConst( p, i ) )
502:             {
503:                 iObjRaw = Gia_ManCorrSpecReal( pNew, p, pObj, nFrames, 0 );
504:                 iObjNew = Abc_LitNotCond( iObjRaw, Gia_ObjPhase(pObj) );
505:                 if ( iObjNew != 0 )
506:                 {
507:                     Vec_IntPush( *pvOutputs, 0 );
508:                     Vec_IntPush( *pvOutputs, i );
509:                     if ( pvOutLits )
510:                     {
511:                         Vec_IntPush( *pvOutLits, 0 );
512:                         Vec_IntPush( *pvOutLits, iObjRaw );
513:                     }
514:                     Vec_IntPush( vXorLits, iObjNew );
515:                 }
516:             }
517:             else if ( Gia_ObjIsHead( p, i ) )
518:             {
519:                 iPrev = i;
520:                 Gia_ClassForEachObj1( p, i, iObj )
521:                 {
522:                     iPrevRaw = Gia_ManCorrSpecReal( pNew, p, Gia_ManObj(p, iPrev), nFrames, 0 );
523:                     iObjRaw  = Gia_ManCorrSpecReal( pNew, p, Gia_ManObj(p, iObj), nFrames, 0 );
524:                     iPrevNew = Abc_LitNotCond( iPrevRaw, Gia_ObjPhase(pObj) ^ Gia_ObjPhase(Gia_ManObj(p, iPrev)) );
525:                     iObjNew  = Abc_LitNotCond( iObjRaw,  Gia_ObjPhase(pObj) ^ Gia_ObjPhase(Gia_ManObj(p, iObj)) );
526:                     if ( iPrevNew != iObjNew && iPrevNew != 0 && iObjNew != 1 )
527:                     {
528:                         Vec_IntPush( *pvOutputs, iPrev );
529:                         Vec_IntPush( *pvOutputs, iObj );
530:                         if ( pvOutLits )
531:                         {
532:                             Vec_IntPush( *pvOutLits, iPrevRaw );
533:                             Vec_IntPush( *pvOutLits, iObjRaw );
534:                         }
535:                         Vec_IntPush( vXorLits, Gia_ManHashAnd(pNew, iPrevNew, Abc_LitNot(iObjNew)) );
536:                     }
537:                     iPrev = iObj;
538:                 }
539:                 iObj = i;
540:                 iPrevRaw = Gia_ManCorrSpecReal( pNew, p, Gia_ManObj(p, iPrev), nFrames, 0 );
541:                 iObjRaw  = Gia_ManCorrSpecReal( pNew, p, Gia_ManObj(p, iObj), nFrames, 0 );
542:                 iPrevNew = Abc_LitNotCond( iPrevRaw, Gia_ObjPhase(pObj) ^ Gia_ObjPhase(Gia_ManObj(p, iPrev)) );
543:                 iObjNew  = Abc_LitNotCond( iObjRaw,  Gia_ObjPhase(pObj) ^ Gia_ObjPhase(Gia_ManObj(p, iObj)) );
544:                 if ( iPrevNew != iObjNew && iPrevNew != 0 && iObjNew != 1 )
545:                 {
546:                     Vec_IntPush( *pvOutputs, iPrev );
547:                     Vec_IntPush( *pvOutputs, iObj );
548:                     if ( pvOutLits )
549:                     {
550:                         Vec_IntPush( *pvOutLits, iPrevRaw );
551:                         Vec_IntPush( *pvOutLits, iObjRaw );
552:                     }
553:                     Vec_IntPush( vXorLits, Gia_ManHashAnd(pNew, iPrevNew, Abc_LitNot(iObjNew)) );
554:                 }
555:             }
556:         }
557:     }
558:     else
559:     {
560:         Gia_ManForEachObj1( p, pObj, i )
561:         {
562:             pRepr = Gia_ObjReprObj( p, Gia_ObjId(p,pObj) );
563:             if ( pRepr == NULL )
564:                 continue;
565:             iPrevRaw = Gia_ObjIsConst(p, i)? 0 : Gia_ManCorrSpecReal( pNew, p, pRepr, nFrames, 0 );
566:             iObjRaw  = Gia_ManCorrSpecReal( pNew, p, pObj, nFrames, 0 );
567:             iPrevNew = iPrevRaw;
568:             iObjNew  = Abc_LitNotCond( iObjRaw, Gia_ObjPhase(pRepr) ^ Gia_ObjPhase(pObj) );
569:             if ( iPrevNew != iObjNew )
570:             {
571:                 Vec_IntPush( *pvOutputs, Gia_ObjId(p, pRepr) );
572:                 Vec_IntPush( *pvOutputs, Gia_ObjId(p, pObj) );
573:                 if ( pvOutLits )
574:                 {
575:                     Vec_IntPush( *pvOutLits, iPrevRaw );
576:                     Vec_IntPush( *pvOutLits, iObjRaw );
577:                 }
578:                 Vec_IntPush( vXorLits, Gia_ManHashXor(pNew, iPrevNew, iObjNew) );
579:             }
580:         }
581:     }
582:     Vec_IntForEachEntry( vXorLits, iObjNew, i )
583:         Gia_ManAppendCo( pNew, iObjNew );
584:     Vec_IntFree( vXorLits );
585:     Gia_ManHashStop( pNew );
586:     Vec_IntErase( &p->vCopies );
587: //Abc_Print( 1, "Before sweeping = %d\n", Gia_ManAndNum(pNew) );
588:     pNew = Gia_ManCleanup( pTemp = pNew );
589:     if ( pvOutLits )
590:         Gia_ManDupRemapLiterals( *pvOutLits, pTemp );

