1379: int Gia_ManCheckRefinements( Gia_Man_t * p, Vec_Str_t * vStatus, Vec_Int_t * vOutputs, Cec_ManSim_t * pSim, int fRings )
1380: {
1381:     int i, status, iRepr, iObj;
1382:     int Counter = 0;
1383:     assert( 2 * Vec_StrSize(vStatus) == Vec_IntSize(vOutputs) );
1384:     Vec_StrForEachEntry( vStatus, status, i )
1385:     {
1386:         iRepr = Vec_IntEntry( vOutputs, 2*i );
1387:         iObj  = Vec_IntEntry( vOutputs, 2*i+1 );
1388:         if ( status == 1 )
1389:             continue;
1390:         if ( status == 0 )
1391:         {
1392:             // Match upstream ABC: do not force-split when SAT returns a CEX.
1393:             // Cec_ManResimulateCounterExamples replays the CEX and refines the
